<section class="grid stats"><?php foreach ($summary as $label => $n): ?><div class="card stat"><div class="num"><?= $e($n) ?></div><div class="muted"><?= $e($label) ?></div></div><?php endforeach; ?></section>
<section class="card"><h2>Matching quality indicator</h2><p>Average score of the top-ranked provider across all matching runs: <strong><?= $avgTop === null ? 'no data yet' : $e($avgTop) ?></strong></p></section>
<section class="card"><h2>Requests by category</h2><table><thead><tr><th>Category</th><th>Requests</th><th>Completed</th></tr></thead><tbody><?php foreach ($byCategory as $c): ?><tr><td><?= $e($c['name']) ?></td><td><?= $e($c['requests']) ?></td><td><?= $e($c['completed'] ?? 0) ?></td></tr><?php endforeach; ?></tbody></table></section>
<section class="card"><h2>CSV exports</h2><p class="muted">Exports contain only the columns listed; credentials, tokens and file contents are never included. Exports are recorded in the activity log.</p>
<ul class="plain"><?php foreach ($defs as $key => $d): ?><li><a href="<?= $e($url('/reports/export', ['type' => $key])) ?>"><?= $e($d['title']) ?></a> <span class="muted"><?= $e(implode(', ', $d['headers'])) ?></span></li><?php endforeach; ?></ul></section>
